#!/usr/bin/env bash
# POD_FIX_ONE_LINER.sh — one-liner to CLEAN useless H3 files + BAKE correct Abiray Q4_K_M for 24GB
# Abiray RELIGION: https://huggingface.co/Abiray/MiniMax-H3-Pruned-GGUF
#   CORRECT: MiniMax-H3-Ref2VA-Pruned-Q4_K_M.gguf 11.6G (Q5 14.1G for 24GB HQ) + qwen3vl_nvfp4_awq + video_vae int8 + audio_vae
#   USELESS: fp8 19.5G (OOM), FL2VA, Q2/Q3/Q5/Q6/Q8, unsloth Q4 duplicate — fills 70GB volume
# Usage in Pod Terminal (paste ONE LINE):
#   curl -sSL https://raw.githubusercontent.com/Alfa-jim/darkcoal-h3-new/main/POD_FIX_ONE_LINER.sh | bash
# Or paste the ONE-LINER below directly:
set -e
VOL=$([ -d /workspace ] && echo /workspace || echo /runpod-volume); echo ">>> VOL=$VOL  $(df -h $VOL | tail -1)"; echo ">>> CLEAN useless H3..."; rm -fv $VOL/models/diffusion_models/minimax_h3_ref2va_pruned_fp8* $VOL/models/unet/minimax_h3_ref2va_pruned_fp8* $VOL/models/diffusion_models/MiniMax-H3-FL2VA* $VOL/models/diffusion_models/minimax_h3_fl2va* $VOL/models/diffusion_models/MiniMax-H3-Ref2VA-Pruned-Q2*.gguf $VOL/models/diffusion_models/MiniMax-H3-Ref2VA-Pruned-Q3*.gguf $VOL/models/diffusion_models/MiniMax-H3-Ref2VA-Pruned-Q5*.gguf $VOL/models/diffusion_models/MiniMax-H3-Ref2VA-Pruned-Q6*.gguf $VOL/models/diffusion_models/MiniMax-H3-Ref2VA-Pruned-Q8*.gguf $VOL/models/diffusion_models/minimax_h3_ref2va_pruned-Q4_K.gguf $VOL/models/diffusion_models/*.tmp $VOL/models/diffusion_models/*.part $VOL/models/text_encoders/qwen3vl_32b_minimax_h3-Q4_K_M.gguf 2>/dev/null || true; echo ">>> cleaned — free now $(df -h $VOL | tail -1)"; pip install -q --upgrade huggingface_hub hf_transfer; export HF_HUB_ENABLE_HF_TRANSFER=1; huggingface-cli download Abiray/MiniMax-H3-Pruned-GGUF MiniMax-H3-Ref2VA-Pruned-Q4_K_M.gguf --local-dir $VOL/models/diffusion_models --local-dir-use-symlinks False; huggingface-cli download Comfy-Org/MiniMax-H3 qwen3vl_32b_minimax_h3_nvfp4_awq.safetensors --local-dir $VOL/models/text_encoders --local-dir-use-symlinks False 2>&1 | tail -5 || true; huggingface-cli download Comfy-Org/MiniMax-H3 minimax_h3_video_vae_int8_convrot.safetensors --local-dir $VOL/models/vae --local-dir-use-symlinks False 2>&1 | tail -5 || true; huggingface-cli download Comfy-Org/MiniMax-H3 minimax_h3_audio_vae_fp32.safetensors --local-dir $VOL/models/vae --local-dir-use-symlinks False 2>&1 | tail -5 || true; mkdir -p $VOL/models/unet; ln -sf $VOL/models/diffusion_models/MiniMax-H3-Ref2VA-Pruned-Q4_K_M.gguf $VOL/models/unet/MiniMax-H3-Ref2VA-Pruned-Q4_K_M.gguf; mkdir -p /runpod-volume/models/diffusion_models /runpod-volume/models/unet /runpod-volume/models/text_encoders /runpod-volume/models/vae 2>/dev/null || true; ln -sf $VOL/models/diffusion_models/MiniMax-H3-Ref2VA-Pruned-Q4_K_M.gguf /runpod-volume/models/diffusion_models/MiniMax-H3-Ref2VA-Pruned-Q4_K_M.gguf 2>/dev/null || true; ln -sf $VOL/models/diffusion_models/MiniMax-H3-Ref2VA-Pruned-Q4_K_M.gguf /runpod-volume/models/unet/MiniMax-H3-Ref2VA-Pruned-Q4_K_M.gguf 2>/dev/null || true; [ -f $VOL/models/text_encoders/qwen3vl_32b_minimax_h3_nvfp4_awq.safetensors ] && ln -sf $VOL/models/text_encoders/qwen3vl_32b_minimax_h3_nvfp4_awq.safetensors /runpod-volume/models/text_encoders/qwen3vl_32b_minimax_h3_nvfp4_awq.safetensors 2>/dev/null || true; for f in minimax_h3_video_vae_int8_convrot.safetensors minimax_h3_audio_vae_fp32.safetensors; do [ -f $VOL/models/vae/$f ] && ln -sf $VOL/models/vae/$f /runpod-volume/models/vae/$f 2>/dev/null || true; done; echo ">>> DONE — verify:"; ls -lh $VOL/models/diffusion_models/MiniMax-H3-Ref2VA-Pruned-Q4_K_M.gguf $VOL/models/text_encoders/qwen* $VOL/models/vae/minimax* 2>/dev/null | sed 's/^/  /'; head -c 4 $VOL/models/diffusion_models/MiniMax-H3-Ref2VA-Pruned-Q4_K_M.gguf | grep -q GGUF && echo "  ✔ GGUF magic OK" || echo "  ✗ GGUF BAD"; df -h $VOL | tail -1 | awk '{print "  Disk free: "$4" used: "$3" size: "$2}'; echo ">>> STOP Pod — volume persists. Serverless: ghcr.io/alfa-jim/darkcoal-h3-new:latest Disk 25GB GPU 24GB"
